Return ONLY this JSON shape:

{

  "summary": "one short sentence about current conditions",

  "rainRisk": "none|low|medium|high",

  "rainingNow": false,

  "suggestions": [

    {

      "title": "short title",

      "why": "one short reason tied to weather/mood/mode",

      "indoorFriendly": false

    }

  ],

  "caution": null

}



Constraints:

- suggestions must contain exactly 3 items

- caution is string or null

- rainingNow is boolean

- rainRisk must be one of: none, low, medium, high

language: {{$var[language]}}

mode: {{$var[mode]}}

mood: {{$var[mood]}}



Weather interpretation JSON:

{{Weather Coach[data.response]}}



Candidates (Wikipedia geosearch):

{{POI Search[data.response.query.geosearch]}}



Pick exactly one candidate.



Return ONLY this JSON shape:

{

  "pageid": 0,

  "title": "exact title from candidate",

  "lat": 0,

  "lon": 0,

  "distMeters": 0,

  "why": "one short reason in the requested language",

  "fitsWeather": true

}



Constraints:

- pageid, lat, lon, distMeters must come from the chosen candidate (use candidate.dist for distMeters)

- title must match the candidate title exactly

- fitsWeather is boolean

- why max ~25 words

input.script:
let raw = {{Pick POI[data.response]}};
if (typeof raw === "string") {
  raw = JSON.parse(raw);
}
if (typeof raw === "string") {
  raw = JSON.parse(raw); // double-encoded fallback
}
process.stdout.write(String(raw.pageid));

function parseMaybe(v) {
  let x = v;
  if (typeof x === "string") x = JSON.parse(x);
  if (typeof x === "string") x = JSON.parse(x);
  return x;
}

const weather = parseMaybe({{Weather Coach[data.response]}});
const pick = parseMaybe({{Pick POI[data.response]}});
const narration = parseMaybe({{Narration[data.response]}});

const result = {
  ok: true,
  input: {
    latitude: Number({{$var[latitude]n}}),
    longitude: Number({{$var[longitude]n}}),
    language: {{$var[language]}},
    mood: {{$var[mood]}},
    mode: {{$var[mode]}},
    radiusMeters: Number({{$var[radiusMeters]n}})
  },
  weather,
  place: pick,
  narration
};

process.stdout.write(JSON.stringify(result));
